import { terminateOwnedProcessTree } from "../🪓️termination/🟦️.ts";
import { StringDecoder } from "node:string_decoder";
import { spawn, spawnSync } from "node:child_process";


/** ⏱️ Keeps long native queue waits observable until the owning operation completes. */
export function startNativeProgress(label: string, intervalMs = 10_000, output: (line: string) => void = (line) => console.log(line)): () => void {
  const started = Date.now(),
    progress = setInterval(() => output(`[${label}] running elapsedMs=${Date.now() - started}`), intervalMs);
  return () => clearInterval(progress);
}

/** 🏃️ Runs a bounded owned command with progress and process-tree cancellation. Its stdout (unless ignored) and stderr are piped and
 * forwarded, never inherited: an inherited pipe shares this Bun process's `O_NONBLOCK`, and a burst from the command then fails with
 * `EAGAIN` once a slow reader lets the pipe fill ([[cargoStreamingStatus]], ticket 26/09/23 W4). */
export async function runOwnedCommand(command: string, args: string[], cwd: string, label: string, timeoutMs: number, options: { stdout?: "inherit" | "ignore"; env?: Readonly<Record<string, string | undefined>>; signal?: AbortSignal; onLine?: (line: string) => void; onProgress?: (line: string) => void } = {}): Promise<void> {
  if (options.signal?.aborted) throw new Error(`${label} stopped: cancelled`);
  const child = spawn(command, args, { cwd, env: options.env ?? process.env, detached: process.platform !== "win32", stdio: ["inherit", options.stdout === "ignore" ? "ignore" : "pipe", "pipe"], windowsHide: true });
  child.stdout?.pipe(process.stdout, { end: false });
  child.stderr!.pipe(process.stderr, { end: false });
  let stopped = "",
    forceKill: ReturnType<typeof setTimeout> | undefined;
  const terminate = (reason: string): void => {
    stopped ||= reason;
    if (!child.pid) return;
    if (process.platform === "win32") spawnSync("taskkill", ["/pid", String(child.pid), "/t", "/f"], { stdio: "ignore", windowsHide: true });
    else {
      try {
        process.kill(-child.pid, "SIGTERM");
      } catch {}
      forceKill ??= setTimeout(() => {
        try {
          process.kill(-child.pid!, "SIGKILL");
        } catch {}
      }, 2_000);
      forceKill.unref();
    }
  };
  const abort = (): void => { stopped ||= "cancelled"; if (child.pid) terminateOwnedProcessTree(child.pid); };
  const observe = (stream: NodeJS.ReadableStream): void => {
    const decoder = new StringDecoder("utf8");
    let pending = "";
    stream.on("data", (bytes: Buffer) => {
      pending += decoder.write(bytes);
      let boundary: number;
      while ((boundary = pending.indexOf("\n")) >= 0) {
        options.onLine!(pending.slice(0, boundary).replace(/\r$/u, ""));
        pending = pending.slice(boundary + 1);
      }
    });
    stream.once("end", () => { pending += decoder.end(); if (pending) options.onLine!(pending); });
  };
  if (options.onLine) { if (child.stdout) observe(child.stdout); observe(child.stderr!); }
  options.signal?.addEventListener("abort", abort, { once: true });
  if (options.signal?.aborted) abort();
  const interrupt = (): void => terminate("SIGINT");
  const stop = (): void => terminate("SIGTERM");
  process.once("SIGINT", interrupt);
  process.once("SIGTERM", stop);
  const stopProgress = startNativeProgress(label, 10_000, options.onProgress);
  const timeout = timeoutMs > 0 ? setTimeout(() => terminate(`timeout ${timeoutMs}ms`), timeoutMs) : undefined;
  try {
    const status = await new Promise<number>((accept) => {
      child.once("error", (error) => {
        console.error(error.message);
        accept(1);
      });
      child.once("close", (code) => accept(code ?? 1));
    });
    if (stopped) throw new Error(`${label} stopped: ${stopped}`);
    if (status !== 0) throw new Error(`${label} failed (${status})`);
  } finally {
    options.signal?.removeEventListener("abort", abort);
    stopProgress();
    if (timeout) clearTimeout(timeout);
    if (forceKill) clearTimeout(forceKill);
    process.off("SIGINT", interrupt);
    process.off("SIGTERM", stop);
  }
}

import type { ScriptRouter } from "../🟦️.ts";

export interface RunScriptMainOptions {
  readonly argv?: readonly string[];
  readonly defaultCommand?: string;
  readonly beforeDispatch?: (argv: readonly string[]) => boolean | Promise<boolean>;
}

/** 🚪️ Dispatches owned commands after an optional caller-owned contribution. */
export async function runScriptMain(router: ScriptRouter, options: RunScriptMainOptions = {}): Promise<void> {
  let argv = [...(options.argv ?? process.argv.slice(2))];
  if (await options.beforeDispatch?.([...argv])) return;
  if (options.defaultCommand && !argv.length) argv = [options.defaultCommand];
  if (!router.hasCommands()) throw Error(`usage: ${router.usage()}`);
  await router.run(argv);
}

import { lstatSync } from "node:fs";
import { dirname, isAbsolute, join, parse, relative, resolve, sep } from "node:path";

/** 🧭️Bundle command; `run` receives argv segments after the subcommand (e.g. `dev mcp` → `["mcp"]`). */
export abstract class Script {
  protected readonly root: string;
  protected readonly repoRoot: string;

  constructor(root: string, repoRoot: string) {
    this.root = root;
    this.repoRoot = repoRoot;
  }
  abstract run(segments: string[]): void | Promise<void>;
}

/** 📦️Bundle-scoped command with `root` at the package directory. */
export abstract class BundleScript extends Script {
  constructor(bundleRoot: string, repoRoot?: string) {
    super(bundleRoot, repoRoot ?? findWorkspaceRoot(bundleRoot));
  }
}
export type ScriptCommand = new (root: string, repoRoot: string) => Script;
export type ScriptCommandLoader = () => Promise<ScriptCommand>;

/** 🧭️Declarative subcommand registry for a single `script.ts`. */
export class ScriptRouter {
  private readonly commands = new Map<string, () => ScriptCommand | Promise<ScriptCommand>>();
  readonly bundleRoot: string;
  readonly repoRoot: string;

  constructor(bundleRoot: string, repoRoot: string = findWorkspaceRoot(bundleRoot)) {
    this.bundleRoot = bundleRoot;
    this.repoRoot = repoRoot;
  }

  /** 📌️Registers a subcommand implemented by a `Script` subclass. */
  register(name: string, Command: ScriptCommand): this {
    this.add(name, () => Command);
    return this;
  }

  /** 💤️Loads only the selected command owner, sharing one load across concurrent dispatches. */
  registerLazy(name: string, load: ScriptCommandLoader): this {
    let command: Promise<ScriptCommand> | undefined;
    this.add(name, () => command ??= Promise.resolve().then(load));
    return this;
  }

  private add(name: string, load: () => ScriptCommand | Promise<ScriptCommand>): void {
    if (!name || name.trim() !== name) throw Error("Command name must be nonempty and trimmed");
    if (this.commands.has(name)) throw Error(`Command ${JSON.stringify(name)} is already registered`);
    this.commands.set(name, load);
  }

  /** 📋️Human-readable usage line for this router. */
  usage(): string {
    const names = [...this.commands.keys()];
    if (names.length === 0) return "bun ./📜️script.ts policy";
    return `bun ./📜️script.ts <${names.join("|")}> [args…]`;
  }

  /** 📊️Whether any subcommands are registered (policy-only bundles may have none). */
  hasCommands(): boolean {
    return this.commands.size > 0;
  }

  /** ▶️Dispatches `segments[0]` to a registered command class. */
  async run(segments: string[]): Promise<void> {
    const name = segments[0];
    if (!name) throw Error(`usage: ${this.usage()}`);
    const load = this.commands.get(name);
    if (!load) throw Error(`unknown command ${JSON.stringify(name)}; usage: ${this.usage()}`);
    const Command = await load();
    await Promise.resolve(new Command(this.bundleRoot, this.repoRoot).run(segments.slice(1)));
  }
}

/** 🔎️ Limits paired workspace-marker discovery to one caller-owned ancestry. */
export interface WorkspaceRootSearch {
  readonly stopAt?: string;
}

/** 📁️ Resolves the nearest paired Nx/package owner and refuses missing or escaping roots. */
export function findWorkspaceRoot(start?: string, options: WorkspaceRootSearch = {}): string {
  let directory = resolve(start?.trim() || process.env.NX_WORKSPACE_ROOT?.trim() || process.env.REPO_ROOT?.trim() || process.cwd());
  const boundary = resolve(options.stopAt ?? parse(directory).root), distance = relative(boundary, directory);
  if (isAbsolute(distance) || distance === ".." || distance.startsWith(`..${sep}`)) throw Error("workspace root boundary must contain its start directory");
  for (let depth = 0; depth < 32; depth++) {
    if (["nx.json", "package.json"].every((filename) => lstatSync(join(directory, filename), { throwIfNoEntry: false })?.isFile())) return directory;
    if (directory === boundary) break;
    const parent = dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  throw Error("workspace root with paired Nx and package markers was not found");
}

import { spawnSync } from "node:child_process";

/** 🌳️ Captures the first-party ownership state needed to terminate a live child. */
export interface OwnedChildHandle { readonly pid?: number; readonly exitCode: number | null; readonly signalCode: string | null }

interface OwnedProcessRow {
  pid: number;
  parent: number;
  group: number;
  depth: number;
}

/** 🪓️Terminates one owned subprocess tree, including descendant-created POSIX groups, before ancestry is lost. */
export function terminateOwnedProcessTree(rootPid: number): void {
  if (!Number.isSafeInteger(rootPid) || rootPid <= 0) return;
  if (process.platform === "win32") {
    spawnSync("taskkill", ["/pid", String(rootPid), "/T", "/F"], { stdio: "ignore", windowsHide: true });
    return;
  }
  const snapshot = spawnSync("ps", ["-axo", "pid=,ppid=,pgid="], { encoding: "utf8", windowsHide: true });
  if (snapshot.status !== 0 || typeof snapshot.stdout !== "string") {
    try { process.kill(-rootPid, "SIGKILL"); } catch {}
    try { process.kill(rootPid, "SIGKILL"); } catch {}
    return;
  }
  const rows = snapshot.stdout.split("\n").flatMap((line): Omit<OwnedProcessRow, "depth">[] => {
    const fields = line.trim().split(/\s+/).map(Number);
    return fields.length === 3 && fields.every((field) => Number.isSafeInteger(field) && field > 0)
      ? [{ pid: fields[0]!, parent: fields[1]!, group: fields[2]! }]
      : [];
  });
  const depth = new Map<number, number>([[rootPid, 0]]);
  for (let changed = true; changed;) {
    changed = false;
    for (const row of rows) {
      if (depth.has(row.pid)) continue;
      const parentDepth = depth.get(row.parent);
      if (parentDepth === undefined) continue;
      depth.set(row.pid, parentDepth + 1);
      changed = true;
    }
  }
  const owned: OwnedProcessRow[] = rows.filter((row) => depth.has(row.pid)).map((row) => ({ ...row, depth: depth.get(row.pid)! }));
  if (!owned.some((row) => row.pid === rootPid)) owned.push({ pid: rootPid, parent: 0, group: rootPid, depth: 0 });
  const ownedPids = new Set(owned.map((row) => row.pid));
  const groups = new Map<number, number>();
  for (const row of owned) {
    if (ownedPids.has(row.group)) groups.set(row.group, Math.max(groups.get(row.group) ?? 0, row.depth));
  }
  for (const [group] of [...groups].sort((left, right) => right[1] - left[1])) {
    try { process.kill(-group, "SIGKILL"); } catch {}
  }
  for (const row of owned.sort((left, right) => right.depth - left.depth)) {
    try { process.kill(row.pid, "SIGKILL"); } catch {}
  }
}

/** 🪓️ Terminates one still-running spawned child with its whole descendant tree — POSIX groups and `taskkill /T`
 * on Windows through [[terminateOwnedProcessTree]] — and never signals a pid its exited child no longer owns. */
export function terminateOwnedChildTree(child: OwnedChildHandle): void {
  if (child.exitCode === null && child.signalCode === null && child.pid) terminateOwnedProcessTree(child.pid);
}

/** 🎨️ Deterministic RGBA8 editing shared by browser tools and language-neutral conformance cases. */
export type PixelImage = { width: number; height: number; pixels: Uint8Array };
export type PixelColor = readonly [number, number, number, number];
export type PixelPoint = readonly [number, number];
export type PixelOperation =
  | { kind: "invert" | "grayscale" | "clear" | "flipHorizontal" | "flipVertical" | "rotateClockwise" | "rotateCounterclockwise" }
  | { kind: "brightness" | "contrast" | "saturation" | "gamma" | "threshold" | "posterize" | "blur" | "sharpen"; value: number }
  | { kind: "resize"; width: number; height: number; sampling: "nearest" | "bilinear" }
  | { kind: "crop"; x: number; y: number; width: number; height: number }
  | { kind: "fill"; color: PixelColor }
  | { kind: "alphaFill"; alpha: number; opacity: number }
  | ({ kind: "stroke"; points: readonly PixelPoint[]; erase: boolean } & PixelBrush)
  | ({ kind: "alphaStroke"; points: readonly PixelPoint[] } & PixelAlphaBrush);
export type SelectionShape =
  | { kind: "rectangle" | "ellipse"; x: number; y: number; width: number; height: number }
  | { kind: "polygon"; points: readonly PixelPoint[] };
export type SelectionMerge = "replace" | "add" | "subtract" | "intersect";
export type PixelProgress = { completed: number; total: number; done: boolean };
export type PixelEditOptions = { selection?: Uint8Array; signal?: AbortSignal; chunkPixels?: number; onProgress?: (progress: PixelProgress) => void };
export type PixelBrush = { size: number; opacity: number; hardness: number; color: PixelColor; erase?: boolean };
export type PixelAlphaBrush = { size: number; opacity: number; hardness: number; alpha: number };
export const MAX_IMAGE_SIDE = 16384;
export const MAX_IMAGE_PIXELS = 16 * 1024 * 1024;

const byte = (value: number) => Math.round(Math.max(0, Math.min(255, value)));
const bounded = (value: number, min: number, max: number) => Number.isFinite(value) && value >= min && value <= max;
const invalid = (message: string): never => { throw new RangeError(message); };
const aborted = (): never => { throw new DOMException("Pixel operation cancelled", "AbortError"); };
const yieldTurn = () => new Promise<void>(resolve => setTimeout(resolve, 0));

export function validateExtent(width: number, height: number): number {
  if (!Number.isInteger(width) || !Number.isInteger(height) || !bounded(width, 1, MAX_IMAGE_SIDE) || !bounded(height, 1, MAX_IMAGE_SIDE) || width * height > MAX_IMAGE_PIXELS) invalid("Image extent exceeds the pixel budget");
  return width * height;
}

export function validateImage(image: PixelImage): void {
  if (!(image.pixels instanceof Uint8Array) || image.pixels.length !== validateExtent(image.width, image.height) * 4) invalid("RGBA8 length does not match image extent");
}

function validateMask(mask: Uint8Array | undefined, count: number): void {
  if (mask !== undefined && (!(mask instanceof Uint8Array) || mask.length !== count)) invalid("Selection extent does not match image");
}

function validateColor(color: PixelColor): void {
  if (color.length !== 4 || color.some(v => !Number.isInteger(v) || !bounded(v, 0, 255))) invalid("Color must contain four byte channels");
}

function sample(image: PixelImage, x: number, y: number): PixelColor {
  const index = (Math.max(0, Math.min(image.height - 1, y)) * image.width + Math.max(0, Math.min(image.width - 1, x))) * 4;
  return [image.pixels[index]!, image.pixels[index + 1]!, image.pixels[index + 2]!, image.pixels[index + 3]!];
}

function weightedSample(image: PixelImage, x: number, y: number): PixelColor {
  const x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0;
  const samples = [sample(image,x0,y0),sample(image,x0+1,y0),sample(image,x0,y0+1),sample(image,x0+1,y0+1)];
  const weights = [(1-fx)*(1-fy),fx*(1-fy),(1-fx)*fy,fx*fy];
  let alpha = 0;
  const rgb = [0,0,0];
  for (let i = 0; i < 4; i++) {
    const a = samples[i]![3] * weights[i]!;
    alpha += a;
    for (let c = 0; c < 3; c++) rgb[c]! += samples[i]![c]! * a;
  }
  return alpha > 0 ? [byte(rgb[0]! / alpha),byte(rgb[1]! / alpha),byte(rgb[2]! / alpha),byte(alpha)] : [0,0,0,0];
}

export function sourceOver(destination: PixelColor, source: PixelColor, opacity = 1): PixelColor {
  const sa = source[3] / 255 * opacity, da = destination[3] / 255, alpha = sa + da * (1-sa);
  if (alpha === 0) return [0,0,0,0];
  return [byte((source[0]*sa+destination[0]*da*(1-sa))/alpha),byte((source[1]*sa+destination[1]*da*(1-sa))/alpha),byte((source[2]*sa+destination[2]*da*(1-sa))/alpha),byte(alpha*255)];
}

function dimensions(image: PixelImage, operation: PixelOperation): readonly [number, number] {
  if (operation.kind === "rotateClockwise" || operation.kind === "rotateCounterclockwise") return [image.height, image.width];
  if (operation.kind === "resize" || operation.kind === "crop") return [operation.width, operation.height];
  return [image.width, image.height];
}

function validateOperation(image: PixelImage, operation: PixelOperation, selected: boolean): void {
  if (!operation || typeof operation !== "object") invalid("Pixel operation is required");
  const numeric: Record<string, readonly [number, number]> = { brightness:[-1,1],contrast:[-1,1],saturation:[-1,1],gamma:[0.01,10],threshold:[0,255],posterize:[2,256],blur:[0,16],sharpen:[0,5] };
  if ("value" in operation) {
    const range = numeric[operation.kind];
    if (!range || !bounded(operation.value,range[0],range[1])) invalid("Invalid filter parameter");
    if (["blur","posterize"].includes(operation.kind) && !Number.isInteger(operation.value)) invalid("Filter parameter must be an integer");
  } else if (operation.kind === "stroke" || operation.kind === "alphaStroke") {
    validateBrush(operation.points,operation);
  } else if (operation.kind === "alphaFill") {
    if (!Number.isInteger(operation.alpha) || !bounded(operation.alpha,0,255) || !bounded(operation.opacity,0,1)) invalid("Invalid alpha fill");
  } else if (operation.kind === "fill") validateColor(operation.color);
  else if (operation.kind === "crop") {
    if (![operation.x,operation.y].every(v => Number.isInteger(v) && v >= 0) || operation.x + operation.width > image.width || operation.y + operation.height > image.height) invalid("Crop lies outside image");
  } else if (operation.kind === "resize") {
    if (!["nearest","bilinear"].includes(operation.sampling)) invalid("Unknown resize sampling");
  } else if (!["invert","grayscale","clear","flipHorizontal","flipVertical","rotateClockwise","rotateCounterclockwise"].includes(operation.kind)) invalid("Unknown pixel operation");
  const [width,height] = dimensions(image,operation);
  validateExtent(width,height);
  if (selected && ["crop","resize","flipHorizontal","flipVertical","rotateClockwise","rotateCounterclockwise"].includes(operation.kind)) invalid("Geometry operations require an unrestricted image");
}

function filtered(image: PixelImage, x: number, y: number, operation: PixelOperation, coverage = 1): PixelColor {
  const original = sample(image,x,y);
  if (operation.kind === "alphaFill") return [original[0],original[1],original[2],byte(original[3]+(operation.alpha-original[3])*operation.opacity*coverage)];
  if (operation.kind === "clear") return [0,0,0,0];
  if (operation.kind === "fill") return sourceOver(original,operation.color,coverage);
  if (operation.kind === "stroke" || operation.kind === "alphaStroke") {
    const radius=operation.size/2,core=radius*operation.hardness;
    let amount=0;
    for(let i=0;i<operation.points.length;i++) {
      const from=operation.points[Math.max(0,i-1)]!,to=operation.points[i]!;
      const distance=segmentDistance(x+0.5,y+0.5,from,to);
      amount=Math.max(amount,distance>radius?0:distance<=core?255:byte(255*(radius-distance)/(radius-core)));
    }
    const opacity=amount/255*operation.opacity*coverage;
    return brushPixel(original,operation,opacity);
  }
  if (operation.kind === "flipHorizontal") return sample(image,image.width-x-1,y);
  if (operation.kind === "flipVertical") return sample(image,x,image.height-y-1);
  if (operation.kind === "rotateClockwise") return sample(image,y,image.height-x-1);
  if (operation.kind === "rotateCounterclockwise") return sample(image,image.width-y-1,x);
  if (operation.kind === "crop") return sample(image,x+operation.x,y+operation.y);
  if (operation.kind === "resize") {
    if (operation.sampling === "nearest") return sample(image,Math.floor((x+0.5)*image.width/operation.width),Math.floor((y+0.5)*image.height/operation.height));
    return weightedSample(image,(x+0.5)*image.width/operation.width-0.5,(y+0.5)*image.height/operation.height-0.5);
  }
  if (operation.kind === "blur" || operation.kind === "sharpen") {
    if (operation.value === 0) return original;
    const radius = operation.kind === "blur" ? operation.value : 1;
    const rgb = [0,0,0];
    let alpha = 0, count = 0;
    for (let dy = -radius; dy <= radius; dy++) for (let dx = -radius; dx <= radius; dx++) {
      const neighbor = sample(image,x+dx,y+dy);
      alpha += neighbor[3];
      for (let c = 0; c < 3; c++) rgb[c]! += neighbor[c]! * neighbor[3];
      count++;
    }
    const blur = alpha > 0 ? rgb.map(v => v/alpha) : [0,0,0];
    return operation.kind === "blur"
      ? [byte(blur[0]!),byte(blur[1]!),byte(blur[2]!),byte(alpha/count)]
      : [byte(original[0]+operation.value*(original[0]-blur[0]!)),byte(original[1]+operation.value*(original[1]-blur[1]!)),byte(original[2]+operation.value*(original[2]-blur[2]!)),original[3]];
  }
  const luma = 0.2126*original[0]+0.7152*original[1]+0.0722*original[2];
  const map = (v: number): number => {
    switch (operation.kind) {
      case "invert": return 255-v;
      case "grayscale": return luma;
      case "brightness": return v+operation.value*255;
      case "contrast": return (v-127.5)*Math.pow(2,operation.value*4)+127.5;
      case "saturation": return luma+(v-luma)*(operation.value+1);
      case "gamma": return 255*Math.pow(v/255,1/operation.value);
      case "threshold": return luma >= operation.value ? 255 : 0;
      case "posterize": return Math.round(v/255*(operation.value-1))*255/(operation.value-1);
    }
    return invalid("Unknown color operation");
  };
  return [byte(map(original[0])),byte(map(original[1])),byte(map(original[2])),original[3]];
}

/** 🧵️ An owned unpublished candidate; callers retain the source until completion. */
export class PixelEditJob {
  private source: PixelImage;
  private output: PixelImage;
  private operation: PixelOperation;
  private selection?: Uint8Array;
  private cursor = 0;
  private cancelled = false;
  constructor(image: PixelImage, operation: PixelOperation, selection?: Uint8Array) {
    validateImage(image);
    validateMask(selection,image.width*image.height);
    validateOperation(image,operation,selection !== undefined);
    this.source = { ...image, pixels: image.pixels.slice() };
    this.operation = structuredClone(operation);
    this.selection = selection?.slice();
    const [width,height] = dimensions(image,operation);
    this.output = {width,height,pixels:new Uint8Array(width*height*4)};
  }
  advance(pixelBudget = 4096): PixelProgress {
    if (this.cancelled) aborted();
    if (!Number.isInteger(pixelBudget) || !bounded(pixelBudget,1,65536)) invalid("Pixel budget must be 1–65536");
    const total = this.output.width*this.output.height;
    const end = Math.min(total,this.cursor+pixelBudget);
    for (; this.cursor < end; this.cursor++) {
      const x = this.cursor%this.output.width, y = Math.floor(this.cursor/this.output.width);
      const coverage = (this.selection?.[this.cursor] ?? 255)/255;
      const before = sample(this.source,x,y);
      const after = coverage === 0 ? before : filtered(this.source,x,y,this.operation,coverage);
      const mix = this.operation.kind === "fill" || this.operation.kind === "stroke" || this.operation.kind === "alphaStroke" || this.operation.kind === "alphaFill" ? 1 : coverage;
      for (let c = 0; c < 4; c++) this.output.pixels[this.cursor*4+c] = byte(before[c]!+(after[c]!-before[c]!)*mix);
      if (this.operation.kind === "clear" && coverage > 0 && coverage < 1) {
        for (let c = 0; c < 3; c++) this.output.pixels[this.cursor*4+c] = this.output.pixels[this.cursor*4+3] ? before[c]! : 0;
      }
    }
    return {completed:this.cursor,total,done:this.cursor === total};
  }
  cancel(): void {
    this.cancelled = true;
    this.output.pixels = new Uint8Array();
    this.source.pixels = new Uint8Array();
    this.selection = undefined;
  }
  result(): PixelImage {
    if (this.cancelled) aborted();
    if (this.cursor !== this.output.width*this.output.height) throw new Error("Pixel operation is incomplete");
    return {...this.output,pixels:this.output.pixels.slice()};
  }
}

export async function editImage(image: PixelImage, operation: PixelOperation, options: PixelEditOptions = {}): Promise<PixelImage> {
  if (options.signal?.aborted) aborted();
  if(operation.kind === "stroke") return paintStroke(image,operation.points,operation,options);
  if(operation.kind === "alphaStroke") return paintAlphaStroke(image,operation.points,operation,options);
  const job = new PixelEditJob(image,operation,options.selection);
  try {
    while (true) {
      if (options.signal?.aborted) aborted();
      const progress = job.advance(options.chunkPixels ?? (operation.kind === "blur" ? 128 : 4096));
      options.onProgress?.(progress);
      if (options.signal?.aborted) aborted();
      if (progress.done) return job.result();
      await yieldTurn();
    }
  } catch (error) {
    job.cancel();
    throw error;
  }
}

function validateShape(shape:SelectionShape):void {
  if (shape.kind === "polygon") {
    if (shape.points.length < 3 || shape.points.length > 4096 || shape.points.some(p => p.length !== 2 || !p.every(Number.isFinite))) invalid("Polygon needs 3–4096 finite points");
  } else if (!["rectangle","ellipse"].includes(shape.kind) || ![shape.x,shape.y,shape.width,shape.height].every(Number.isFinite)) invalid("Invalid selection shape");
}

/** 🪢️ Scanline selection rasterization with bounded row grants. */
export class PixelSelectionJob {
  private mask:Uint8Array;
  private row=0;
  private cancelled=false;
  private shape:SelectionShape;
  constructor(private width:number,private height:number,shape:SelectionShape) {
    validateShape(shape);
    this.mask=new Uint8Array(validateExtent(width,height));this.shape=structuredClone(shape);
  }
  advance(rows=16):PixelProgress {
    if(this.cancelled) aborted();
    if(!Number.isInteger(rows)||!bounded(rows,1,64)) invalid("Selection grant must be 1–64 rows");
    const end=Math.min(this.height,this.row+rows),shape=this.shape;
    for(;this.row<end;this.row++) {
      const y=this.row+0.5;
      const fill=(left:number,right:number,inclusive=false)=>{
        const from=Math.max(0,Math.min(this.width,Math.ceil(left-0.5)));
        const to=Math.max(from,Math.min(this.width,inclusive?Math.floor(right-0.5)+1:Math.ceil(right-0.5)));
        this.mask.fill(255,this.row*this.width+from,this.row*this.width+to);
      };
      if(shape.kind==="polygon") {
        const intersections:number[]=[];
        for(let i=0,j=shape.points.length-1;i<shape.points.length;j=i++) {
          const a=shape.points[i]!,b=shape.points[j]!;
          if((a[1]>y)!==(b[1]>y)) intersections.push((b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]);
        }
        intersections.sort((a,b)=>a-b);
        for(let i=0;i+1<intersections.length;i+=2) fill(intersections[i]!,intersections[i+1]!);
      } else {
        const left=Math.min(shape.x,shape.x+shape.width),top=Math.min(shape.y,shape.y+shape.height),w=Math.abs(shape.width),h=Math.abs(shape.height);
        if(w===0||h===0||y<top||y>top+h) continue;
        if(shape.kind==="rectangle") {if(y<top+h)fill(left,left+w);}
        else {
          const radius=w/2*Math.sqrt(Math.max(0,1-((y-top-h/2)/(h/2))**2));
          fill(left+w/2-radius,left+w/2+radius,true);
        }
      }
    }
    return {completed:this.row,total:this.height,done:this.row===this.height};
  }
  result():Uint8Array {
    if(this.cancelled) aborted();
    if(this.row!==this.height) throw new Error("Selection is incomplete");
    return this.mask.slice();
  }
  cancel():void {this.cancelled=true;this.mask=new Uint8Array();}
}

export function selectionMask(width:number,height:number,shape:SelectionShape):Uint8Array {
  const job=new PixelSelectionJob(width,height,shape);
  while(!job.advance(64).done) {}
  return job.result();
}

export async function selectPixels(width:number,height:number,shape:SelectionShape,options:PixelEditOptions={}):Promise<Uint8Array> {
  if(options.signal?.aborted) aborted();
  const job=new PixelSelectionJob(width,height,shape);
  try {
    while(true) {
      if(options.signal?.aborted) aborted();
      const progress=job.advance();options.onProgress?.(progress);
      if(options.signal?.aborted) aborted();
      if(progress.done) return job.result();
      await yieldTurn();
    }
  } catch(error) {job.cancel();throw error;}
}

export class SelectionCombineJob {
  private output:Uint8Array;
  private cursor=0;
  private cancelled=false;
  constructor(private readonly current:Uint8Array|undefined,private readonly next:Uint8Array,private readonly mode:SelectionMerge) {
    if(!(next instanceof Uint8Array)||next.length<1||next.length>MAX_IMAGE_PIXELS) invalid("Selection exceeds the pixel budget");
    validateMask(current,next.length);
    if(!["replace","add","subtract","intersect"].includes(mode)) invalid("Unknown selection merge");
    this.output=new Uint8Array(next.length);
  }
  advance(pixelBudget=32768):PixelProgress {
    if(this.cancelled) aborted();
    if(!Number.isSafeInteger(pixelBudget)||pixelBudget<0) invalid("Invalid selection work budget");
    const end=Math.min(this.next.length,this.cursor+Math.min(pixelBudget,32768));
    for(;this.cursor<end;this.cursor++) {
      const a=this.current?.[this.cursor]??0,b=this.next[this.cursor]!;
      this.output[this.cursor]=this.mode==="replace"?b:this.mode==="add"?Math.max(a,b):this.mode==="subtract"?Math.max(0,a-b):Math.min(a,b);
    }
    return {completed:this.cursor,total:this.next.length,done:this.cursor===this.next.length};
  }
  cancel():void {this.cancelled=true;this.output=new Uint8Array();}
  result():Uint8Array {
    if(this.cancelled) aborted();
    if(this.cursor!==this.next.length) invalid("Selection combination is incomplete");
    return this.output;
  }
}
export async function combineSelections(current:Uint8Array|undefined,next:Uint8Array,mode:SelectionMerge,options:PixelEditOptions={}):Promise<Uint8Array> {
  if(options.signal?.aborted) aborted();
  const budget=options.chunkPixels??32768;
  if(!Number.isSafeInteger(budget)||budget<1) invalid("Invalid selection work budget");
  const job=new SelectionCombineJob(current,next,mode);
  try {
    while(true) {
      if(options.signal?.aborted) aborted();
      const progress=job.advance(budget);options.onProgress?.(progress);
      if(options.signal?.aborted) aborted();
      if(progress.done) return job.result();
      await yieldTurn();
    }
  } catch(error) {job.cancel();throw error;}
}

export async function floodSelection(image: PixelImage, x: number, y: number, tolerance: number, options: PixelEditOptions = {}): Promise<Uint8Array> {
  validateImage(image);
  validateMask(options.selection,image.width*image.height);
  if (!Number.isInteger(x) || !Number.isInteger(y) || !bounded(x,0,image.width-1) || !bounded(y,0,image.height-1) || !bounded(tolerance,0,255)) invalid("Invalid flood selection seed or tolerance");
  if (options.signal?.aborted) aborted();
  image={...image,pixels:image.pixels.slice()};
  options={...options,selection:options.selection?.slice()};
  const total = image.width*image.height, mask = new Uint8Array(total), seen = new Uint8Array(total), queue = new Uint32Array(total);
  const target = sample(image,x,y), seed = y*image.width+x;
  let head = 0, tail = 1;
  queue[0] = seed;
  seen[seed] = 1;
  const admit = (index: number) => {
    if (!seen[index]) { seen[index] = 1; queue[tail++] = index; }
  };
  while (head < tail) {
    const end = Math.min(tail,head+4096);
    for (; head < end; head++) {
      const index = queue[head]!, px = index%image.width, py = Math.floor(index/image.width);
      const color = sample(image,px,py);
      if (options.selection?.[index] === 0 || Math.max(...color.map((v,c) => Math.abs(v-target[c]!))) > tolerance) continue;
      mask[index] = options.selection?.[index] ?? 255;
      if (px > 0) admit(index-1);
      if (px+1 < image.width) admit(index+1);
      if (py > 0) admit(index-image.width);
      if (py+1 < image.height) admit(index+image.width);
    }
    options.onProgress?.({completed:head,total,done:head === tail});
    if (options.signal?.aborted) aborted();
    if (head < tail) await yieldTurn();
  }
  options.onProgress?.({completed:total,total,done:true});
  return mask;
}

function segmentDistance(x: number, y: number, from: PixelPoint, to: PixelPoint): number {
  const dx = to[0]-from[0], dy = to[1]-from[1], length = dx*dx+dy*dy;
  const t = length === 0 ? 0 : Math.max(0,Math.min(1,((x-from[0])*dx+(y-from[1])*dy)/length));
  return Math.hypot(x-from[0]-t*dx,y-from[1]-t*dy);
}

function validateBrush(points:readonly PixelPoint[],brush:PixelBrush|PixelAlphaBrush):void {
  if("alpha" in brush) {if(!Number.isInteger(brush.alpha)||!bounded(brush.alpha,0,255))invalid("Alpha must be a byte");}
  else validateColor(brush.color);
  if (!bounded(brush.size,0.1,4096) || !bounded(brush.opacity,0,1) || !bounded(brush.hardness,0,1) || !points.length || points.length > 2048 || points.some(p => p.length !== 2 || !p.every(Number.isFinite))) invalid("Invalid brush stroke");
}

/** 🔲️ A pixel-aligned rectangle of an image. */
export type PixelRect = { x: number; y: number; width: number; height: number };

/** 🔲️ Every pixel a brush of `size` along `points` can reach on a `width × height` image: the union of each segment's box
 * widened by the radius and clipped to the image — exactly the rectangles `paintStroke` walks; `null` when the stroke lies
 * wholly outside. Twin of the Rust `stroke_bounds` the replayed raster stroke leaf paints over. */
export function strokeBounds(points: readonly PixelPoint[], size: number, width: number, height: number): PixelRect | null {
  if (width <= 0 || height <= 0) return null;
  const radius = size/2;
  let bounds: [number, number, number, number] | null = null;
  for (let segment = 0; segment < points.length; segment++) {
    const from = points[Math.max(0,segment-1)]!, to = points[segment]!;
    const left = Math.max(0,Math.floor(Math.min(from[0],to[0])-radius)), right = Math.min(width-1,Math.ceil(Math.max(from[0],to[0])+radius));
    const top = Math.max(0,Math.floor(Math.min(from[1],to[1])-radius)), bottom = Math.min(height-1,Math.ceil(Math.max(from[1],to[1])+radius));
    if (left > right || top > bottom) continue;
    bounds = bounds === null ? [left,top,right,bottom] : [Math.min(bounds[0],left),Math.min(bounds[1],top),Math.max(bounds[2],right),Math.max(bounds[3],bottom)];
  }
  return bounds === null ? null : {x:bounds[0],y:bounds[1],width:bounds[2]-bounds[0]+1,height:bounds[3]-bounds[1]+1};
}

export async function paintStroke(image: PixelImage, points: readonly PixelPoint[], brush: PixelBrush, options: PixelEditOptions = {}): Promise<PixelImage> {
  return paintBrush(image,points,brush,options);
}

/** 🎭️ Paint coverage independently of RGB, including fully hidden pixels. */
export async function paintAlphaStroke(image:PixelImage,points:readonly PixelPoint[],brush:PixelAlphaBrush,options:PixelEditOptions={}):Promise<PixelImage> {
  return paintBrush(image,points,brush,options);
}

function brushPixel(before:PixelColor,brush:PixelBrush|PixelAlphaBrush,amount:number):PixelColor {
  if(amount===0)return before;
  if("alpha" in brush)return [before[0],before[1],before[2],byte(before[3]+(brush.alpha-before[3])*amount)];
  if(!brush.erase)return sourceOver(before,brush.color,amount);
  const alpha=byte(before[3]*(1-amount));
  return alpha>0?[before[0],before[1],before[2],alpha]:[0,0,0,0];
}

async function paintBrush(image:PixelImage,points:readonly PixelPoint[],brush:PixelBrush|PixelAlphaBrush,options:PixelEditOptions):Promise<PixelImage> {
  validateImage(image);
  validateMask(options.selection,image.width*image.height);
  validateBrush(points,brush);
  if (options.signal?.aborted) aborted();
  image={...image,pixels:image.pixels.slice()};
  points=structuredClone(points);brush=structuredClone(brush);
  options={...options,selection:options.selection?.slice()};
  const pixels = image.pixels.slice(), coverage = new Uint8Array(image.width*image.height), radius = brush.size/2;
  for (let segment = 0; segment < points.length; segment++) {
    const from = points[Math.max(0,segment-1)]!, to = points[segment]!;
    const minX = Math.max(0,Math.floor(Math.min(from[0],to[0])-radius)), maxX = Math.min(image.width-1,Math.ceil(Math.max(from[0],to[0])+radius));
    const minY = Math.max(0,Math.floor(Math.min(from[1],to[1])-radius)), maxY = Math.min(image.height-1,Math.ceil(Math.max(from[1],to[1])+radius));
    for (let y = minY; y <= maxY; y++) {
      for (let x = minX; x <= maxX; x++) {
        const d = segmentDistance(x+0.5,y+0.5,from,to), core = radius*brush.hardness;
        const amount = d > radius ? 0 : d <= core ? 255 : byte(255*(radius-d)/(radius-core));
        const index = y*image.width+x;
        coverage[index] = Math.max(coverage[index]!,amount);
      }
      if ((y-minY)%16 === 15) {
        if (options.signal?.aborted) aborted();
        await yieldTurn();
      }
    }
    options.onProgress?.({completed:segment+1,total:points.length+1,done:false});
    if (options.signal?.aborted) aborted();
    if (segment%32 === 31) await yieldTurn();
  }
  for (let index = 0; index < coverage.length; index++) {
    if (index%65536 === 65535) {
      if (options.signal?.aborted) aborted();
      await yieldTurn();
    }
    const amount = coverage[index]!/255*(options.selection?.[index] ?? 255)/255*brush.opacity;
    if (amount === 0) continue;
    const before = sample(image,index%image.width,Math.floor(index/image.width));
    pixels.set(brushPixel(before,brush,amount),index*4);
  }
  options.onProgress?.({completed:points.length+1,total:points.length+1,done:true});
  if (options.signal?.aborted) aborted();
  return {width:image.width,height:image.height,pixels};
}

/** 🧪️ Language-neutral pixel editing cases and independent libvips image oracles. */
import { describe, expect, test } from "bun:test";
import sharp from "sharp";
import Ajv from "ajv";
import fixtures from "../🧫️fixtures/🔣️.json";
import schema from "../🧬️schema/🔣️.json";
import { editImage, selectionMask, selectPixels, combineSelections, SelectionCombineJob, type SelectionMerge, floodSelection, paintStroke, PixelEditJob, PixelSelectionJob, strokeBounds, validateImage, type PixelOperation, type PixelPoint, type SelectionShape } from "../🟦️.ts";

const image = () => ({ ...fixtures.image, pixels: Uint8Array.from(fixtures.image.pixels) });
describe("pixel editing contract", () => {
  const validate = new Ajv().compile(schema);
  for (const fixture of fixtures.cases) test(fixture.name, async () => {
    const source="image" in fixture?fixture.image!:fixtures.image;
    expect(validate({image: source, operation: fixture.operation, ...("selection" in fixture ? {selection: fixture.selection} : {})})).toBe(true);
    const input = {...source,pixels:Uint8Array.from(source.pixels)};
    const result = await editImage(input, fixture.operation as PixelOperation, { selection: "selection" in fixture ? Uint8Array.from(fixture.selection!) : undefined });
    expect([...result.pixels]).toEqual(fixture.expected);
    expect([...input.pixels]).toEqual(source.pixels);
    if("width" in fixture && fixture.width !== undefined && fixture.height !== undefined) expect([result.width,result.height]).toEqual([fixture.width,fixture.height]);
  });
  for (const fixture of fixtures.selections) test(fixture.name, () => {
    expect([...selectionMask("width" in fixture ? fixture.width! : 2, "height" in fixture ? fixture.height! : 2, fixture.shape as SelectionShape)]).toEqual(fixture.expected);
  });
  test("libvips independently verifies flips, rotations, crops and inversion", async () => {
    for (const [kind, apply] of [
      ["flipHorizontal", (s: sharp.Sharp) => s.flop()],
      ["flipVertical", (s: sharp.Sharp) => s.flip()],
      ["rotateClockwise", (s: sharp.Sharp) => s.rotate(90)],
      ["rotateCounterclockwise", (s: sharp.Sharp) => s.rotate(270)],
      ["invert", (s: sharp.Sharp) => s.negate({alpha: false})],
    ] as const) {
      const source = image();
      const oracle = await apply(sharp(source.pixels, {raw:{width:2,height:2,channels:4}})).raw().toBuffer();
      expect([...((await editImage(source, {kind})).pixels)]).toEqual([...oracle]);
    }
    const oracle = await sharp(image().pixels, {raw:{width:2,height:2,channels:4}}).extract({left:1,top:0,width:1,height:1}).raw().toBuffer();
    expect([...((await editImage(image(), {kind:"crop",x:1,y:0,width:1,height:1})).pixels)]).toEqual([...oracle]);
  });
  test("selection merge operations preserve coverage", async () => {
    const a = Uint8Array.of(255,0,128), b = Uint8Array.of(0,255,255);
    expect([...await combineSelections(a,b,"add")]).toEqual([255,255,255]);
    expect([...await combineSelections(a,b,"subtract")]).toEqual([255,0,0]);
    expect([...await combineSelections(a,b,"intersect")]).toEqual([0,0,128]);
    expect([...await combineSelections(a,b,"replace")]).toEqual([...b]);
  });
  test("libvips independently verifies box convolution",async()=>{
    const source={width:3,height:1,pixels:Uint8Array.of(0,0,0,255,90,90,90,255,180,180,180,255)};
